window.A3_DASHBOARD_UNITS = [{"unit":1,"theme":"alternative – constantly","cards":[{"w":"alternative","p":"n.","d":"another choice","c":"替代方案","s":"Given the situation, the team explored another alternative.","t":"考慮到情況，團隊探索了另一個替代方案。"},{"w":"alternative","p":"adj.","d":"that can be used instead of something else","c":"替代的","s":"We are looking for an alternative solution to this problem.","t":"我們正在尋找此問題的替代解決方案。"},{"w":"circumstances","p":"n.","d":"the facts or situation around an event","c":"情況","s":"Due to unforeseen circumstances, the event has been postponed.","t":"由於無法預見的情況，活動已被延期。"},{"w":"under the circumstance","p":"phr.","d":"because of the situation","c":"在這種情況下","s":"under the circumstance , I believe we made the right decision.","t":"在這種情況下，我相信我們做出了正確的決定。"},{"w":"comment on","p":"v.","d":"to give your opinion about something","c":"評論","s":"The professor will comment on your paper once it's submitted.","t":"一旦提交，教授將評論您的論文。"},{"w":"make a comment on","p":"n.","d":"to say your opinion about something","c":"對...做出評論","s":"She didn't make a comment on the artist's new exhibition.","t":"她沒有對藝術家的新展覽做出評論。"},{"w":"compensate","p":"v.","d":"to pay someone for loss or harm","c":"賠償","s":"Due to the delay, the airline decided to compensate its passengers.","t":"由於延遲，航空公司決定賠償其乘客。"},{"w":"compensation","p":"n.","d":"money paid for loss or harm","c":"賠償金","s":"He received a substantial amount in compensation for the accident.","t":"他因事故收到了大筆賠償金。"},{"w":"compensation","p":"n.","d":"money paid for work","c":"薪資","s":"The average compensation, or salary for start-ups are ten times higher than that of employees in traditional manufacturing industries.","t":"新創企業的平均薪資是傳統製造業員工的十倍。"},{"w":"component","p":"n.","d":"one part of a machine or system","c":"組件","s":"That small component is essential for the machine to work properly.","t":"那小組件對機器的正常工作至關重要。"},{"w":"consent","p":"n.","d":"permission or agreement","c":"同意","s":"They proceeded with the project after getting the consent of the local community.","t":"在得到當地社區的同意後，他們繼續進行該項目。"},{"w":"consent","p":"adj.","d":"agreed by everyone","c":"同意的","s":"It's a consent decision between both parties.","t":"這是雙方的共同決定。"},{"w":"consider","p":"v.","d":"to think carefully about something","c":"考慮","s":"Did you consider the implications of your decision?","t":"你考慮過你的決定的含義嗎？"},{"w":"consideration","p":"n.","d":"careful thought","c":"考慮","s":"The main consideration for our choice was the quality of the product.","t":"我們選擇的主要考慮是產品的質量。"},{"w":"take...into consideration","p":"phr.","d":"to think about something before deciding","c":"考慮到...","s":"You should take into consideration his feelings when making such a decision.","t":"做出這樣的決定時，你應該考慮到他的感受。"},{"w":"considerate","p":"adj.","d":"kind and caring about others' feelings","c":"體貼的","s":"He is always considerate and thinks of others before himself.","t":"他總是體貼並在自己之前考慮別人。"},{"w":"considerable","p":"adj.","d":"large in amount or size","c":"相當大的","s":"The damage caused a considerable amount of financial loss.","t":"損害造成了相當大的財務損失。"},{"w":"considerably","p":"adv.","d":"by a large amount","c":"相當地","s":"The costs have risen considerably since last year.","t":"費用自去年以來已經大幅上升。"},{"w":"constant","p":"adj.","d":"happening all the time","c":"持續的","s":"The constant noise from the construction site is annoying.","t":"來自工地的持續噪音很煩人。"},{"w":"constantly","p":"adv.","d":"all the time","c":"不斷地","s":"He's constantly checking his phone for updates.","t":"他不斷地查看手機以獲取更新。"}]},{"unit":2,"theme":"constrain – deduction","cards":[{"w":"constrain","p":"v.","d":"to limit or control something","c":"限制","s":"Limited resources might constrain our ability to complete the project on time.","t":"有限的資源可能會限制我們及時完成項目的能力。"},{"w":"constraint","p":"n.","d":"something that limits what you can do","c":"限制","s":"The budgetary constraint affected the scope of the project.","t":"預算限制影響了項目的範圍。"},{"w":"contribute to","p":"v.","d":"to help cause something","c":"有助於","s":"Healthy eating can contribute to overall well-being.","t":"健康飲食可以有助於整體健康。"},{"w":"make a contribution to","p":"phr.","d":"to give help to make something happen","c":"對...作出貢獻","s":"Volunteering can allow you to make a contribution to the community.","t":"志願工作可以讓您對社區作出貢獻。"},{"w":"convention","p":"n.","d":"a large meeting or conference","c":"會議","s":"The annual tech convention attracted innovators from around the world.","t":"年度技術會議吸引了來自世界各地的創新者。"},{"w":"convention = tradition","p":"n.","d":"a usual way of doing things","c":"傳統","s":"The village has a convention of celebrating the harvest with a big feast.","t":"這個村莊有一個慶祝豐收的大餐的傳統。"},{"w":"conventional","p":"adj.","d":"traditional and usual","c":"傳統的","s":"They opted for a more conventional approach to the problem.","t":"他們選擇了一種更傳統的方法來解決問題。"},{"w":"coordinate","p":"v.","d":"to organize people or things to work together","c":"協調","s":"We need to coordinate our efforts to be more efficient.","t":"我們需要協調我們的努力以更加高效。"},{"w":"coordination","p":"n.","d":"organizing people to work well together","c":"協調","s":"The event required the coordination of multiple teams.","t":"這個活動需要多個團隊的協調。"},{"w":"core","p":"n.","d":"the most important part","c":"核心","s":"Trust is the core of any strong relationship.","t":"信任是任何堅強關係的核心。"},{"w":"core value","p":"phr.","d":"the most important belief or idea","c":"核心價值","s":"Integrity is one of the company's core value.","t":"誠信是該公司的核心價值之一。"},{"w":"corporate","p":"adj.","d":"about a large company","c":"企業的","s":"He attended a corporate training seminar last week.","t":"他上週參加了一場企業培訓研討會。"},{"w":"corporation","p":"n.","d":"a large company","c":"公司","s":"The corporation announced a new CEO today.","t":"該公司今天宣布了一位新CEO。"},{"w":"correspond with","p":"v.","d":"to match or agree with something","c":"與...相對應","s":"The symptoms correspond with those described in the medical textbook.","t":"症狀與醫學教材中描述的相對應。"},{"w":"correspondent","p":"n.","d":"a reporter in a special place or on a topic","c":"通訊記者","s":"The news correspondent provided updates from the front lines.","t":"新聞通訊記者從前線提供了更新。"},{"w":"corresponding","p":"adj.","d":"matching or connected to something","c":"相對應的","s":"The corresponding numbers were found on the next page.","t":"相對應的數字在下一頁上找到。"},{"w":"criterion","p":"n.","d":"a standard used to judge something","c":"標準","s":"The main criterion for the job is experience in the field.","t":"該工作的主要標準是該領域的經驗。"},{"w":"criteria","p":"n.","d":"standards used to judge something (plural)","c":"標準","s":"There are several criteria for selecting the right candidate.","t":"選擇合適候選人有幾個標準。"},{"w":"deduct","p":"v.","d":"to take away an amount from a total","c":"扣除","s":"They will deduct taxes from your monthly salary.","t":"他們將從您的月薪中扣除稅款。"},{"w":"deduction","p":"n.","d":"an amount taken away from a total","c":"扣除","s":"The deduction was clearly indicated in the invoice.","t":"發票中明確指出了扣除項。"}]},{"unit":3,"theme":"demonstrate = display, explain – exclusive","cards":[{"w":"demonstrate = display, explain","p":"v.","d":"to show or explain how something works","c":"展示，解釋","s":"She used a chart to demonstrate the sales growth.","t":"她使用圖表來展示銷售增長。"},{"w":"demonstrate = protest","p":"v.","d":"to protest in public","c":"抗議","s":"The citizens will demonstrate against the new law.","t":"公民將抗議新法律。"},{"w":"demonstration = protest","p":"n.","d":"a public protest","c":"抗議活動","s":"The demonstration was peaceful, with thousands marching in the streets.","t":"抗議活動是和平的，數千人在街上遊行。"},{"w":"demonstration = illustration","p":"n.","d":"showing how something works","c":"展示","s":"His demonstration of the software's capabilities was very informative.","t":"他對軟件功能的展示非常有用。"},{"w":"document","p":"n.","d":"an official paper","c":"文件","s":"All the relevant document should be submitted by Friday.","t":"所有相關文件應在星期五之前提交。"},{"w":"document","p":"v.","d":"to write down a record of something","c":"紀錄","s":"It's essential to document any changes made to the project.","t":"對項目進行的任何更改進行記錄至關重要。"},{"w":"dominate","p":"v.","d":"to have power or control over others","c":"主宰，佔優勢","s":"The company continues to dominate in the tech industry.","t":"該公司繼續在科技行業佔據主導地位。"},{"w":"dominant","p":"adj.","d":"most important or powerful","c":"佔優勢的","s":"The dominant theme of the conference was sustainability.","t":"會議的主要主題是可持續性。"},{"w":"dominating","p":"adj.","d":"controlling or most powerful","c":"主導的","s":"The dominating force in the market right now is consumer demand.","t":"市場上現在的主要力量是消費者需求。"},{"w":"male-dominating","p":"adj.","d":"controlled by men","c":"男性主宰的","s":"The engineering field has long been considered a male-dominating profession.","t":"長期以來，工程領域一直被認為是男性主宰的職業。"},{"w":"domination","p":"n.","d":"power or control over others","c":"主宰","s":"The team's domination of the league lasted for several years.","t":"該隊在聯盟的主宰地位持續了好幾年。"},{"w":"emphasize on","p":"v.","d":"to show that something is important","c":"強調","s":"The teacher will emphasize on the importance of regular practice.","t":"老師會強調定期練習的重要性。"},{"w":"lay/put emphasis on","p":"phr.","d":"to show that something is important","c":"強調","s":"The teacher always puts emphasis on understanding the basics before moving on.","t":"老師總是強調在繼續之前要先理解基礎知識。"},{"w":"ensure that","p":"phr.","d":"to make sure that something happens","c":"確保","s":"Please ensure that all the devices are turned off after use.","t":"請確保使用後所有設備都已關閉。"},{"w":"ensure +N","p":"phr.","d":"to make sure of something","c":"確保","s":"This method will ensure accuracy in our results.","t":"這種方法將確保我們結果的準確性。"},{"w":"assure","p":"v.","d":"to tell someone something is true so they don't worry","c":"保證","s":"I can assure you that everything will be ready on time.","t":""},{"w":"reassure","p":"v.","d":"to make someone feel less worried again","c":"再保證","s":"The captain tried to reassure passengers that the turbulence was normal.","t":"機長試圖再次保證乘客這是正常的亂流。"},{"w":"exclude","p":"v.","d":"to leave out or keep out","c":"排除","s":"Please exclude any non-relevant information from the report.","t":"請從報告中排除任何不相關的信息。"},{"w":"excluded","p":"adj.","d":"left out","c":"被排除的","s":"The excluded participants were given feedback on their performance.","t":"被排除的參與者收到了關於他們表現的反饋。"},{"w":"exclusive","p":"adj.","d":"only for some people; not shared","c":"獨家的","s":"This offer is exclusive to our premium members.","t":"此優惠僅限於我們的高級會員。"}]},{"unit":4,"theme":"exclusion – initiate","cards":[{"w":"exclusion","p":"n.","d":"leaving someone or something out","c":"排除","s":"The exclusion of certain groups from the survey skewed the results.","t":"從調查中排除某些群體使結果產生偏見。"},{"w":"include","p":"v.","d":"to have something as a part","c":"包括","s":"The package include accommodation and meals.","t":"套餐包括住宿和膳食。"},{"w":"inclusive","p":"adj.","d":"including everyone or everything","c":"包含的","s":"The price is inclusive of all taxes and fees.","t":"價格包含所有稅費。"},{"w":"including","p":"prep.","d":"having something as a part","c":"包括","s":"All students, including those who are international, are eligible.","t":"所有學生，包括國際學生，都有資格。"},{"w":"included","p":"adj.","d":"part of a group","c":"被包括在內的","s":"All included items are listed in the appendix.","t":"所有包含的項目都列在附錄中。"},{"w":"inclusive of","p":"phr.","d":"containing; counting as part","c":"包含","s":"The tour price is inclusive of all meals and transportation.","t":"旅遊價格包含所有餐飲和交通。"},{"w":"framework","p":"n.","d":"a basic structure or plan","c":"框架","s":"The new policy provides a framework for further reforms.","t":"新政策為進一步的改革提供了框架。"},{"w":"fund","p":"v.","d":"to give money for something","c":"資助","s":"The government will fund the research project.","t":"政府將資助這個研究項目。"},{"w":"fund","p":"n.","d":"an amount of money saved for a purpose","c":"基金","s":"The fund for the school trip is running low.","t":"學校旅行的基金正逐漸減少。"},{"w":"fundamental","p":"adj.","d":"basic and very important","c":"基本的","s":"Understanding the fundamental concepts is crucial for advanced study.","t":"了解基本概念對於高級學習至關重要。"},{"w":"illustrate","p":"v.","d":"to draw pictures for a book","c":"插畫","s":"The book is illustrate by a famous artist.","t":"這本書是由一位著名藝術家插畫的。"},{"w":"illustrate = explain","p":"v.","d":"to explain by using examples","c":"解釋","s":"Use examples to illustrate your point.","t":"使用例子來解釋你的觀點。"},{"w":"illustrated","p":"adj.","d":"having pictures","c":"插圖的","s":"I prefer illustrated children's books for their visual appeal.","t":"我更喜歡有插圖的兒童書，因為它們具有視覺吸引力。"},{"w":"immigrate","p":"v.","d":"to come to live in another country","c":"移民","s":"Many people immigrate to the country for better job opportunities.","t":"許多人為了更好的工作機會移民到這個國家。"},{"w":"immigrant","p":"n.","d":"a person who comes to live in another country","c":"移民","s":"The city is home to a large population of immigrant.","t":"這座城市擁有大量的移民。"},{"w":"immigration","p":"n.","d":"coming to live in another country","c":"移民","s":"The immigration office is extremely busy this time of year.","t":"移民辦公室在這個時候非常繁忙。"},{"w":"imply","p":"v.","d":"to suggest something without saying it directly","c":"暗示","s":"Her silence seemed to imply that she disagreed.","t":"她的沉默似乎暗示她不同意。"},{"w":"implication","p":"n.","d":"a meaning that is suggested, not said","c":"暗示","s":"The implication of the statement was clear to everyone in the room.","t":"該聲明的含義對房間裡的每個人都很明確。"},{"w":"initial","p":"adj.","d":"first; at the beginning","c":"初始的","s":"The initial findings are promising, but more research is needed.","t":"初始的研究結果很有希望，但需要進一步的研究。"},{"w":"initiate","p":"v.","d":"to start something","c":"開始","s":"They plan to initiate a new marketing strategy next quarter.","t":"他們計劃下一季度啟動新的營銷策略。"}]},{"unit":5,"theme":"initiative – the minority group","cards":[{"w":"initiative","p":"n.","d":"a new plan; the will to act first","c":"主動權","s":"Taking the initiative to start the project earned her a lot of respect.","t":"採取主動開始該項目為她贏得了很多尊重。"},{"w":"for instance","p":"phr.","d":"for example","c":"舉例","s":"There are many ways to approach the problem, for instance , we could try brainstorming first.","t":"有很多方法可以解決這個問題，舉例來說，我們可以先嘗試腦力激盪。"},{"w":"interact with","p":"v.","d":"to talk or work with others","c":"與...互動","s":"Children learn when they interact with their peers.","t":"當兒童與他們的同齡人互動時，他們會學到東西。"},{"w":"interaction with","p":"n.","d":"talking or working with others","c":"與...的互動","s":"The interaction with customers is essential for our business.","t":"與客戶的互動對我們的業務至關重要。"},{"w":"justify","p":"v.","d":"to give a good reason for something","c":"證明...是正當的","s":"How do you justify spending so much on a single meal?","t":"你如何證明在一餐上花那麼多錢是正當的？"},{"w":"justified","p":"adj.","d":"fair and having a good reason","c":"有正當理由的","s":"The manager felt that the expenses were completely justified.","t":"經理覺得這些開銷完全是有正當理由的。"},{"w":"justification","p":"n.","d":"a good reason for something","c":"理由","s":"He provided justification for each of his decisions during the meeting.","t":"他在會議期間為他的每一個決定提供了理由。"},{"w":"lay-laid-laid","p":"v.","d":"to put something down","c":"放下","s":"She lay-laid-laid the book on the table and walked away.","t":"她把書放在桌子上然後走開了。"},{"w":"layer","p":"n.","d":"a thin covering over or under something","c":"層","s":"The cake had multiple layer of chocolate and cream.","t":"蛋糕有多層巧克力和奶油。"},{"w":"link to/with","p":"v.","d":"to connect things","c":"連接","s":"Can you link this computer to the main server?","t":"你可以將這台電腦連接到主服務器嗎？"},{"w":"link","p":"n.","d":"a connection; a web address","c":"連結","s":"Click on this link to access the website.","t":"點擊此連結以訪問該網站。"},{"w":"location","p":"n.","d":"a place or position","c":"位置","s":"The location of the conference will be announced later.","t":"會議的地點將在稍後宣布。"},{"w":"be located in","p":"phr.","d":"to be in a certain place","c":"位於","s":"The museum is located in the heart of the city.","t":"博物館位於城市的中心。"},{"w":"maximum","p":"adj./n.","d":"the largest amount possible","c":"最大值","s":"You are allowed a maximum of three bags on the flight.","t":"您在航班上允許攜帶最多三個袋子。"},{"w":"minimum","p":"adj./n.","d":"the smallest amount possible","c":"最小值","s":"The minimum order quantity is 50 units.","t":"最小訂購數量是50個單位。"},{"w":"major","p":"adj.","d":"very important or big","c":"主要的","s":"The major reason for the delay was bad weather.","t":"主要的延遲原因是惡劣的天氣。"},{"w":"minor","p":"adj.","d":"small; not very important","c":"次要的","s":"There were a few minor errors in the report.","t":"報告中有一些次要錯誤。"},{"w":"minor in","p":"v.","d":"to study a second subject at university","c":"輔修","s":"She decided to major in psychology and minor in sociology.","t":"她決定主修心理學並輔修社會學。"},{"w":"the minorities","p":"n.","d":"groups that are smaller in number in a society","c":"少數民族","s":"the minorities often have their own unique cultures and traditions.","t":"少數民族通常有自己獨特的文化和傳統。"},{"w":"the minority group","p":"phr.","d":"a group that is smaller in number","c":"少數族群","s":"The government is taking measures to support the minority group in the country.","t":"政府正在採取措施支持國家的少數族群。"}]},{"unit":6,"theme":"negative – registered","cards":[{"w":"negative","p":"adj./n.","d":"bad or harmful; less than zero","c":"負面的/負值","s":"There was a negative reaction to the new policy.","t":"對新政策有負面反應。"},{"w":"outcome","p":"n.","d":"the final result","c":"結果","s":"The outcome of the experiment was unexpected.","t":"實驗的結果是意想不到的。"},{"w":"partnership","p":"n.","d":"working together in business","c":"合夥關係","s":"They formed a partnership to start a new business venture.","t":"他們組成了一個合夥關係來開始一個新的商業冒險。"},{"w":"philosophy","p":"n.","d":"the study of ideas about life and knowledge","c":"哲學","s":"His philosophy on life is quite optimistic.","t":"他對生活的哲學非常樂觀。"},{"w":"physical","p":"adj.","d":"about the body","c":"身體的","s":"This body builder works out in the gym to enhance his physical strength for the upcoming tournament.","t":"這位健美運動員在健身房鍛煉增強體力，為即將到來的比賽。"},{"w":"physical","p":"adj.","d":"about matter and energy (science)","c":"物理的","s":"Regular physical activity is beneficial for health.","t":"定期的物理活動對健康有益。"},{"w":"physics","p":"n.","d":"the science of matter and energy","c":"物理學","s":"He's studying physics at the university.","t":"他在大學學習物理學。"},{"w":"physically","p":"adv.","d":"in a way related to the body","c":"在物理上","s":"The journey was physically demanding.","t":"這次旅行在身體上要求很高。"},{"w":"proportion","p":"n.","d":"the amount of one thing compared to another","c":"比例","s":"The proportion of men to women in the company is 2:1.","t":"該公司男女的比例是2:1。"},{"w":"proportional","p":"adj.","d":"changing at the same rate","c":"成比例的","s":"The size of the room is proportional to its height.","t":"房間的大小與其高度成比例。"},{"w":"portion","p":"n.","d":"a part of something","c":"一部分","s":"Only a small portion of the cake was left.","t":"蛋糕只剩下一小部分。"},{"w":"publish","p":"v.","d":"to print and sell a book or magazine","c":"出版","s":"They plan to publish the book next month.","t":"他們計劃下個月出版這本書。"},{"w":"published","p":"adj.","d":"printed and made public","c":"已出版的","s":"Her published works have received critical acclaim.","t":"她的已出版作品受到了評論家的讚譽。"},{"w":"publishment","p":"n.","d":"something that is published","c":"出版物","s":"The publishment of his new book has been postponed.","t":"他的新書的出版已被推遲。"},{"w":"publisher","p":"n.","d":"a company that publishes books","c":"出版商","s":"The publisher has rights to print the novel overseas.","t":"出版商有權在海外印刷這部小說。"},{"w":"react with","p":"v.","d":"to change when mixed with another chemical","c":"與...產生反應","s":"The chemical will react with oxygen when heated.","t":"加熱時，該化學物質將與氧氣產生反應。"},{"w":"react to","p":"v.","d":"to act because of something that happened","c":"對...的反應","s":"The suspect react to swiftly to all the allegations and charges with confidence, trying to convince the jury of his innocence.","t":"嫌疑人對所有指控和指控迅速作出反應，充滿信心，試圖讓陪審團相信他是無辜的。"},{"w":"reaction to","p":"n.","d":"an action caused by something","c":"對...的反應","s":"The public had a mixed reaction to the new policy.","t":"公眾對新政策有褒貶不一的反應。"},{"w":"register","p":"v.","d":"to put your name on an official list","c":"註冊","s":"You need to register before attending the event.","t":"您需要在參加活動之前註冊。"},{"w":"registered","p":"adj.","d":"officially recorded on a list","c":"已註冊的","s":"Only registered users can access this part of the website.","t":"只有已註冊的用戶可以訪問網站的這一部分。"}]},{"unit":7,"theme":"registration – specified","cards":[{"w":"registration","p":"n.","d":"putting your name on an official list","c":"註冊","s":"The deadline for registration is next Friday.","t":"註冊的截止日期是下周五。"},{"w":"rely on","p":"v.","d":"to depend on someone or something","c":"依賴","s":"We can't always rely on the weather forecast.","t":"我們不能總是依賴天氣預報。"},{"w":"reliance on","p":"n.","d":"the act of depending on something","c":"依賴","s":"The country's reliance on imported oil is a concern.","t":"該國對進口石油的依賴引起了擔憂。"},{"w":"reliable","p":"adj.","d":"able to be trusted","c":"可靠的","s":"We need a more reliable method to collect data.","t":"我們需要一種更可靠的方法來收集數據。"},{"w":"reliant","p":"adj.","d":"needing someone or something","c":"依賴的","s":"The region is heavily reliant tourism for income.","t":"該地區嚴重依賴旅遊業的收入。"},{"w":"remove from","p":"v.","d":"to take something away from a place","c":"從...中移除","s":"Please remove from the sticker from the glass.","t":"請從玻璃上移除貼紙。"},{"w":"removed","p":"adj.","d":"taken away","c":"被移除的","s":"The outdated information was removed the website.","t":"過時的信息已從網站中刪除。"},{"w":"removal","p":"n.","d":"the act of taking something away","c":"移除","s":"The kidney plays a vital role in the removal of waste products from the blood.","t":"腎臟在清除血液中的廢物方面起著至關重要的作用。"},{"w":"scheme","p":"n.","d":"an official plan","c":"計劃","s":"She devised a clever scheme to increase sales.","t":"她設計了一個巧妙的計劃來增加銷售。"},{"w":"sequence","p":"n.","d":"a set of things in a certain order","c":"連續","s":"The events occurred in a strange sequence.","t":"這些事件以奇怪的順序發生。"},{"w":"in sequence","p":"phr.","d":"in a certain order","c":"按順序","s":"Please arrange these documents in sequence according to date.","t":"請按日期將這些文件按順序排列。"},{"w":"sequent","p":"adj.","d":"following in order","c":"連續的","s":"The movie's events were not in sequent order, making it confusing.","t":"電影的事件不是按連續順序進行的，使其令人困惑。"},{"w":"subsequently","p":"adv.","d":"later; after that","c":"隨後","s":"He missed the train and subsequently arrived late to the meeting.","t":"他錯過了火車，隨後開會遲到了。"},{"w":"sex","p":"n.","d":"being male or female","c":"性別","s":"The survey collected data on age, sex, and occupation of participants.","t":"調查收集了參與者的年齡、性別和職業數據。"},{"w":"sexual","p":"adj.","d":"about sex","c":"性的","s":"The course will also discuss sexual reproduction in plants.","t":"課程還將討論植物的性生殖。"},{"w":"sexuality","p":"n.","d":"a person's sexual feelings and interests","c":"性取向","s":"It's important to promote understanding and acceptance of diverse sexuality.","t":"促進對多樣性取向的理解和接受非常重要。"},{"w":"shift","p":"n.","d":"a period of time when a group works","c":"輪班","s":"She has the night shift at the hospital.","t":"她在醫院有夜班。"},{"w":"shift","p":"v.","d":"to move or change from one position to another","c":"轉移","s":"We need to shift our focus towards more sustainable practices.","t":"我們需要將我們的焦點轉向更具可持續性的做法。"},{"w":"specify","p":"v.","d":"to say exactly what you want","c":"指定","s":"Please specify which items you would like to order.","t":"請指定您想要訂購的物品。"},{"w":"specified","p":"adj.","d":"stated clearly and exactly","c":"指定的","s":"All specified candidates should attend the meeting.","t":"所有指定的候選人應出席會議。"}]},{"unit":8,"theme":"specific – volume","cards":[{"w":"specific","p":"adj.","d":"exact and clear; certain","c":"具體的","s":"Do you have any specific requirements for this project?","t":"您對這個項目有沒有具體的要求？"},{"w":"sufficient","p":"adj.","d":"enough","c":"足夠的","s":"Do we have sufficient resources to complete the project?","t":"我們有足夠的資源完成該項目嗎？"},{"w":"sufficiently","p":"adv.","d":"enough","c":"足夠地","s":"The room wasn't sufficiently heated, so we felt cold.","t":"房間沒有足夠的加熱，所以我們覺得冷。"},{"w":"task","p":"v.","d":"to give someone a job to do","c":"任務","s":"She was task with organizing the event.","t":"她負責組織這次活動。"},{"w":"task","p":"n.","d":"a piece of work to be done","c":"任務","s":"Next task is to analyze the data.","t":"您的下一個任務是分析數據"},{"w":"technical","p":"adj.","d":"about special skills or machines","c":"技術的","s":"We encountered some technical difficulties during the setup.","t":"在設置過程中，我們遇到了一些技術上的困難。"},{"w":"technically","p":"adv.","d":"by the strict meaning of the rules","c":"從技術上講","s":"technically speaking, the code is correct, but it could be optimized.","t":"從技術上講，代碼是正確的，但它可以被優化。"},{"w":"technological","p":"adj.","d":"about new science and machines","c":"科技的","s":"The technological advancements in the last decade have been remarkable.","t":"過去十年的科技進步非常引人注目。"},{"w":"technique","p":"n.","d":"a special way of doing something","c":"技巧","s":"She has mastered the technique of playing the violin.","t":"她掌握了拉小提琴的技巧。"},{"w":"technology","p":"n.","d":"science used to make machines and tools","c":"技術","s":"The impact of technology on society is undeniable.","t":"技術對社會的影響是不可否認的。"},{"w":"valid","p":"adj.","d":"officially accepted; reasonable","c":"有效的","s":"The offer is no longer valid as it expired last month.","t":"由於上個月已過期，該優惠不再有效。"},{"w":"validity","p":"n.","d":"the state of being valid","c":"有效性","s":"We are checking the validity of your claims.","t":"我們正在檢查您的索賠的有效性。"},{"w":"expire","p":"v.","d":"to come to an end; no longer be valid","c":"到期","s":"Your membership will expire at the end of this month.","t":"您的會員資格將在本月底到期。"},{"w":"expired","p":"adj.","d":"too old to be used","c":"已過期的","s":"We cannot use this medicine because it's already expired.","t":"我們不能使用這種藥物，因為它已經過期了。"},{"w":"expiration","p":"n.","d":"the end of a period of time","c":"期滿","s":"The expiration date of the contract is December 31st.","t":"合同的到期日期是12月31日。"},{"w":"volume","p":"n.","d":"the amount of space something fills","c":"體積","s":"The volume of water in the tank is 100 liters.","t":"槽中的水體積為100升。"}]}];
